 final Activity activity;final View root;final EditText composer;final ExecutorService worker=Executors.newSingleThreadExecutor();final ExecutorService images=new ThreadPoolExecutor(2,2,0,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<Runnable>(16),new ThreadPoolExecutor.DiscardOldestPolicy());
