  Object retainedDraft=root.getTag(DRAFT_TAG);Map<String,Object> savedDraft=retainedDraft instanceof Map?Json.obj(retainedDraft):null;String draft=savedDraft==null?a.getSharedPreferences("native-music",0).getString("search_draft",""):Json.str(savedDraft,"text");if(draft!=null){searchInput.setText(draft);Object selection=savedDraft==null?Integer.valueOf(a.getSharedPreferences("native-music",0).getInt("search_selection",draft.length())):savedDraft.get("selection");int at=selection instanceof Number?((Number)selection).intValue():draft.length();searchInput.setSelection(Math.max(0,Math.min(draft.length(),at)));}restoreSearchFocus=savedDraft!=null&&Boolean.TRUE.equals(savedDraft.get("focused"));
  searchInput.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){}public void afterTextChanged(android.text.Editable value){saveSearchDraft();if(value.toString().indexOf('\n')>=0){String query=value.toString().replace("\n","");value.replace(0,value.length(),query);search(query);}}});
  status=label("Search to find music",12);status.setTextColor(0xffa6b8c9);addView(status,new LayoutParams(-1,dp(28)));
