  LinearLayout controls=new LinearLayout(a);controls.setGravity(Gravity.CENTER_VERTICAL);play=label("▶",24);play.setGravity(Gravity.CENTER);play.setContentDescription("Play or pause music");controls.addView(play,new LayoutParams(dp(44),dp(40)));play.setOnClickListener(new OnClickListener(){public void onClick(View v){MediaPanel.controlMusic(activity,root,"toggle",0);paintPlayer();}});seek=new SeekBar(a);controls.addView(seek,new LayoutParams(0,dp(38),1));seek.setMax(1000);seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){dragging=true;}public void onProgressChanged(SeekBar s,int p,boolean user){}public void onStopTrackingTouch(SeekBar s){Map<String,Object> state=MediaPanel.state(root);Object d=state.get("duration_ms");if(d instanceof Number)MediaPanel.controlMusic(activity,root,"seek",(int)(((Number)d).longValue()*s.getProgress()/1000));dragging=false;}});addView(controls);
  scroll=new ScrollView(a);scroll.setClipToPadding(true);results=new LinearLayout(a);results.setOrientation(VERTICAL);scroll.addView(results,new ScrollView.LayoutParams(-1,-2));addView(scroll,new LayoutParams(-1,0,1));
  LinearLayout navigation=new LinearLayout(a);navigation.setBackgroundColor(0xff141414);String[] tabs={"⌂  Home","◎  Explore","▤  Library"};for(int i=0;i<tabs.length;i++){final int tab=i;TextView item=label(tabs[i],12);item.setGravity(Gravity.CENTER);navigation.addView(item,new LayoutParams(0,dp(46),1));item.setOnClickListener(new OnClickListener(){public void onClick(View v){if(tab==2){results.removeAllViews();status.setText("Library · account connection not implemented yet");searchInput.clearFocus();composer.requestFocus();}else if(tab==1){searchInput.requestFocus();}else{Object cached=root.getTag(RESULTS_TAG);if(cached instanceof Map){Map<String,Object> data=Json.obj(Json.obj(cached).get("data"));if(data!=null)renderResults(data);}else status.setText("Search for music to get started");}}});}addView(navigation);

  String previous=a.getSharedPreferences("native-music",0).getString("query","");Object cached=root.getTag(RESULTS_TAG);boolean restored=false;if(cached instanceof Map){Map<String,Object> saved=Json.obj(cached);Object at=saved.get("time");Map<String,Object> data=Json.obj(saved.get("data"));if(previous.equals(saved.get("query"))&&at instanceof Number&&System.currentTimeMillis()>=((Number)at).longValue()&&System.currentTimeMillis()-((Number)at).longValue()<300000&&data!=null){query=previous;renderResults(data);restored=true;}}if(!restored&&!previous.isEmpty())search(previous);
  post(new Runnable(){public void run(){if(closed)return;paintPlayer();postDelayed(this,700);}});
