 int dp(int n){return (int)(getResources().getDisplayMetrics().density*n+.5f);}
 android.graphics.drawable.GradientDrawable background(int color){android.graphics.drawable.GradientDrawable b=new android.graphics.drawable.GradientDrawable();b.setColor(color);b.setCornerRadius(dp(16));return b;}
 TextView label(String text,int size){TextView t=new TextView(activity);t.setText(text);t.setTextSize(size);t.setTextColor(0xfff1f4fa);t.setGravity(Gravity.CENTER_VERTICAL);return t;}
 void bottomInset(int height){/* Input floats above the full-size app; it must not resize the app. */if(getPaddingBottom()!=0)setPadding(dp(6),dp(22),dp(6),0);if(scroll.getPaddingBottom()!=0)scroll.setPadding(0,0,0,0);}
 void search(final String value){if(closed||value.trim().isEmpty())return;query=value.trim();final int version=++generation;status.setText("Searching · "+query);activity.getSharedPreferences("native-music",0).edit().putString("query",query).apply();worker.execute(new Runnable(){public void run(){try{final Map<String,Object> data=runTool(activity,"--flat-playlist","--dump-single-json","ytsearch8:"+value);post(new Runnable(){public void run(){if(closed||generation!=version)return;root.setTag(RESULTS_TAG,Json.map("query",query,"time",System.currentTimeMillis(),"data",data));renderResults(data);}});}catch(final Exception error){post(new Runnable(){public void run(){if(!closed&&generation==version)status.setText("Search failed · "+error.getMessage());}});}}});}
 @SuppressWarnings("unchecked") void renderResults(Map<String,Object> data){results.removeAllViews();Object entries=data.get("entries");int count=0;if(entries instanceof List)for(Object entry:(List<?>)entries){if(!(entry instanceof Map))continue;final Map<String,Object> row=(Map<String,Object>)entry;final String id=Json.str(row,"id"),title=Json.str(row,"title");if(id==null||!id.matches("[A-Za-z0-9_-]{11}")||title==null)continue;String artist=Json.str(row,"channel");if(artist==null)artist="";LinearLayout item=new LinearLayout(activity);item.setOrientation(HORIZONTAL);item.setGravity(Gravity.CENTER_VERTICAL);item.setPadding(dp(10),dp(6),dp(10),dp(6));ImageView artwork=new ImageView(activity);artwork.setScaleType(ImageView.ScaleType.CENTER_CROP);artwork.setBackgroundColor(0xff242424);LayoutParams artLp=new LayoutParams(dp(58),dp(58));artLp.rightMargin=dp(12);item.addView(artwork,artLp);loadArtwork(artwork,id);LinearLayout info=new LinearLayout(activity);info.setOrientation(VERTICAL);TextView name=label(title,15);name.setMaxLines(2);info.addView(name);TextView by=label(artist,11);by.setTextColor(0xffa6b8c9);info.addView(by);item.addView(info,new LayoutParams(0,-2,1));TextView go=label("▶",18);item.addView(go,new LayoutParams(dp(28),dp(40)));results.addView(item,new LayoutParams(-1,-2));item.setContentDescription("Play "+title+" by "+artist);item.setOnClickListener(new OnClickListener(){public void onClick(View v){select(id,title);}});count++;}status.setText(count==0?"No results · try another search":"Songs · "+query);}
 void saveSearchDraft(){root.setTag(DRAFT_TAG,Json.map("text",searchInput.getText().toString(),"selection",Math.max(0,searchInput.getSelectionStart()),"focused",searchInput.hasFocus()));draftHandler.removeCallbacks(persistSearchDraft);draftHandler.postDelayed(persistSearchDraft,220);}
 boolean restoreEditorFocus(){return restoreSearchFocus&&searchInput.requestFocus();}
 void loadArtwork(final ImageView image,final String id){image.setTag(id);try{images.execute(new Runnable(){public void run(){java.net.HttpURLConnection connection=null;try{connection=(java.net.HttpURLConnection)new java.net.URL("https://i.ytimg.com/vi/"+id+"/hqdefault.jpg").openConnection();connection.setConnectTimeout(2500);connection.setReadTimeout(2500);java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();try(InputStream in=connection.getInputStream()){byte[] buffer=new byte[4096];int count;while((count=in.read(buffer))!=-1){if(bytes.size()+count>262144)throw new IOException("Artwork too large");bytes.write(buffer,0,count);}}byte[] encoded=bytes.toByteArray();android.graphics.BitmapFactory.Options options=new android.graphics.BitmapFactory.Options();options.inSampleSize=2;final android.graphics.Bitmap bitmap=android.graphics.BitmapFactory.decodeByteArray(encoded,0,encoded.length,options);post(new Runnable(){public void run(){if(!closed&&id.equals(image.getTag())&&bitmap!=null)image.setImageBitmap(bitmap);}});}catch(Exception ignored){}finally{if(connection!=null)connection.disconnect();}}});}catch(RejectedExecutionException ignored){}}
 void select(final String id,final String title){final int version=++generation;status.setText("Loading · "+title);worker.execute(new Runnable(){public void run(){try{final Map<String,Object> data=runTool(activity,"--dump-single-json","--skip-download","-f","bestaudio[ext=m4a]/bestaudio","https://www.youtube.com/watch?v="+id);final String url=Json.str(data,"url");if(url==null||!url.startsWith("https://"))throw new IOException("No playable stream");post(new Runnable(){public void run(){if(closed||generation!=version)return;MediaPanel.openMusic(activity,root,url,title);status.setText("Songs · "+query);paintPlayer();}});}catch(final Exception failure){post(new Runnable(){public void run(){if(!closed&&generation==version)status.setText("Could not load · "+failure.getMessage());}});}}});}
 static Map<String,Object> runTool(Activity activity,String... args)throws Exception{File tool=new File(activity.getFilesDir(),"work/trough-lab/dogshit-player/tools/yt-dlp"),out=File.createTempFile("music-",".json",activity.getCacheDir()),err=File.createTempFile("music-",".log",activity.getCacheDir());Process process=null;try{ArrayList<String> cmd=new ArrayList<String>();cmd.add(new File(Root.os(),"d/usr/bin/python3").getPath());cmd.add(tool.getAbsolutePath());cmd.add("--no-warnings");cmd.add("--no-playlist");cmd.add("--socket-timeout");cmd.add("10");Collections.addAll(cmd,args);ProcessBuilder builder=new ProcessBuilder(Root.command(activity,cmd.toArray(new String[cmd.size()])));builder.environment().putAll(Root.env(activity,activity.getCacheDir()));builder.redirectOutput(out);builder.redirectError(err);process=builder.start();if(!process.waitFor(40,TimeUnit.SECONDS))throw new IOException("Connection timed out");if(process.exitValue()!=0)throw new IOException("Source unavailable; try another track");if(out.length()>4*1024*1024)throw new IOException("Response too large");return Json.obj(Json.parse(new String(java.nio.file.Files.readAllBytes(out.toPath()),"UTF-8")));}finally{if(process!=null)process.destroy();out.delete();err.delete();}}
 void paintPlayer(){Map<String,Object> s=MediaPanel.state(root);boolean ready=Boolean.TRUE.equals(s.get("ready")),playing=Boolean.TRUE.equals(s.get("playing"));play.setText(playing?"Ⅱ":"▶");play.setEnabled(ready);String title=Json.str(s,"title");if(title!=null&&!title.isEmpty())now.setText(title);Object duration=s.get("duration_ms"),position=s.get("position_ms");if(!dragging&&duration instanceof Number&&position instanceof Number&&((Number)duration).longValue()>0)seek.setProgress((int)(1000*((Number)position).longValue()/((Number)duration).longValue()));String error=Json.str(s,"error");if(error!=null&&!error.isEmpty())status.setText(error);}
